import React, { useRef, useState } from 'react';
import html2canvas from 'html2canvas';
import jsPDF from 'jspdf';
const AlertHistory: React.FC = () => {
  const [severity, setSeverity] = useState('');
  const [status, setStatus] = useState('');
  const [expandedId, setExpandedId] = useState<number | null>(null);
  const reportTemplateRef = useRef<HTMLDivElement>(null);
  // Alertes statiques cohérentes avec les attaques détectables par votre modèle
  const [alerts, setAlerts] = useState([
    {
      id: 1,
      timestamp: new Date(Date.now() - 7200000).toISOString(),
      src_ip: '203.45.67.89',
      dst_ip: '192.168.1.1',
      protocol: 'TCP',
      port: 80,
      attack_type: 'DDoS Attack (SYN flood)',
      confidence: 0.98,
      severity: 'critical',
      explanation: 'High rate of SYN packets from multiple sources detected',
      status: 'new',
      notes: ''
    },
    {
      id: 2,
      timestamp: new Date(Date.now() - 5400000).toISOString(),
      src_ip: '185.142.53.12',
      dst_ip: '192.168.1.1',
      protocol: 'TCP',
      port: 22,
      attack_type: 'SSH Brute Force',
      confidence: 0.95,
      severity: 'critical',
      explanation: 'Multiple failed login attempts from single IP',
      status: 'acknowledged',
      notes: 'IP blocked via firewall'
    },
    {
      id: 3,
      timestamp: new Date(Date.now() - 3600000).toISOString(),
      src_ip: '45.142.182.99',
      dst_ip: '192.168.1.1',
      protocol: 'TCP',
      port: 443,
      attack_type: 'Port Scan (TCP SYN)',
      confidence: 0.87,
      severity: 'high',
      explanation: 'Systematic probing of multiple ports detected',
      status: 'new',
      notes: ''
    },
    {
      id: 4,
      timestamp: new Date(Date.now() - 1800000).toISOString(),
      src_ip: '192.168.1.100',
      dst_ip: '10.0.0.5',
      protocol: 'UDP',
      port: 53,
      attack_type: 'UDP Flood (DoS)',
      confidence: 0.92,
      severity: 'high',
      explanation: 'Large volume of UDP packets to DNS port',
      status: 'new',
      notes: ''
    },
    {
      id: 5,
      timestamp: new Date(Date.now() - 300000).toISOString(),
      src_ip: '198.51.100.7',
      dst_ip: '192.168.1.1',
      protocol: 'ICMP',
      port: 0,
      attack_type: 'ICMP Flood (Ping flood)',
      confidence: 0.79,
      severity: 'medium',
      explanation: 'High rate of ICMP echo requests',
      status: 'new',
      notes: ''
    }
  ]);

  // Filtrage local
  const filteredAlerts = alerts.filter(a => 
    (severity === '' || a.severity === severity) &&
    (status === '' || a.status === status)
  );

  // Fonctions d'export (simulées, à connecter à l'API si besoin)
  
  const handleExportPDF = async () => {
    const input = reportTemplateRef.current;
    if (!input) return;

    try {
      // Capturer l'élément en image
      const canvas = await html2canvas(input, {
        scale: 2, // Meilleure qualité d'image
        logging: false,
        useCORS: true // Utile si vous avez des images externes
      });
      
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({
        unit: 'px',
        format: 'a4',
        orientation: 'portrait'
      });

      // Calculer les proportions pour que l'image tienne sur la largeur de la page A4
      const imgWidth = pdf.internal.pageSize.getWidth();
      const imgHeight = (canvas.height * imgWidth) / canvas.width;
      
      pdf.addImage(imgData, 'PNG', 0, 0, imgWidth, imgHeight);
      pdf.save(`alertes_${new Date().toISOString().slice(0,19)}.pdf`);
    } catch (error) {
      console.error('Erreur lors de la génération du PDF', error);
    }
  };

  // Action "Marquer comme reconnu" – modifie l'état local
  const handleAcknowledge = (id: number) => {
    setAlerts(prevAlerts =>
      prevAlerts.map(alert =>
        alert.id === id && alert.status === 'new'
          ? { ...alert, status: 'acknowledged' }
          : alert
      )
    );
  };

  // Action "Ajouter une note" (simple console pour l'exemple)
  const handleAddNote = (id: number) => {
    const note = prompt('Ajouter une note :');
    if (note) {
      setAlerts(prevAlerts =>
        prevAlerts.map(alert =>
          alert.id === id ? { ...alert, notes: note } : alert
        )
      );
    }
  };
 
const downloadCSV = () => {
  // En-têtes des colonnes
  const headers = [
    "Horodatage",
    "IP Source",
    "IP Destination",
    "Protocole",
    "Port",
    "Type d'attaque",
    "Confiance (%)",
    "Sévérité",
    "Statut",
    "Explication",
    "Notes"
  ];

  // Transformation des données filtrées
  const rows = filteredAlerts.map(alert => [
    new Date(alert.timestamp).toLocaleString(),
    alert.src_ip,
    alert.dst_ip,
    alert.protocol,
    alert.port,
    alert.attack_type,
    Math.round(alert.confidence * 100),
    alert.severity,
    alert.status,
    alert.explanation,
    alert.notes || ""
  ]);

  // Construction du contenu CSV (séparateur point-virgule)
  const csvContent = [headers, ...rows].map(row => row.join(";")).join("\n");

  // Téléchargement
  const blob = new Blob(["\uFEFF" + csvContent], { type: "text/csv;charset=utf-8;" });
  const link = document.createElement("a");
  const url = URL.createObjectURL(blob);
  link.href = url;
  link.setAttribute("download", `alertes_${new Date().toISOString().slice(0,19)}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};
  return (
    <div className="alert-history-container">
      <div className="monitoring-header">
        <h1 className="page-title">Historique des Alertes</h1>
        <div className="export-buttons">
           <button className="btn btn-secondary" onClick={downloadCSV}>
            📥 CSV
          </button>
          <button className="btn btn-secondary" onClick={handleExportPDF}>
            📥 PDF
          </button>
        </div>
      </div>

      <div className="filter-section">
        <div className="filter-group">
          <label>Sévérité</label>
          <select value={severity} onChange={(e) => setSeverity(e.target.value)}>
            <option value="">Tous les niveaux</option>
            <option value="low">Bas</option>
            <option value="medium">Moyen</option>
            <option value="high">Haut</option>
            <option value="critical">Critique</option>
          </select>
        </div>
        <div className="filter-group">
          <label>Statut</label>
          <select value={status} onChange={(e) => setStatus(e.target.value)}>
            <option value="">Tous les statuts</option>
            <option value="new">Nouveau</option>
            <option value="acknowledged">Reconnu</option>
            <option value="resolved">Résolu</option>
          </select>
        </div>
      </div>

      <div className="alerts-list">
        {filteredAlerts.map(alert => (
          <div key={alert.id} className="alert-item">
            <div
              className="alert-header"
              onClick={() => setExpandedId(expandedId === alert.id ? null : alert.id)}
            >
              <div className="alert-title">
                <span className={`severity ${alert.severity}`}>
                  {alert.severity.toUpperCase()}
                </span>
                <h3>{alert.attack_type}</h3>
                <div className="alert-meta">
                  <span>{alert.src_ip}</span>
                  <span>→</span>
                  <span>{alert.dst_ip}</span>
                </div>
              </div>
              <span>{expandedId === alert.id ? '▼' : '▶'}</span>
            </div>

            {expandedId === alert.id && (
              <div className="alert-details">
                <div className="detail-row">
                  <label>Heure</label>
                  <p>{new Date(alert.timestamp).toLocaleString()}</p>
                </div>
                <div className="detail-row">
                  <label>IP Source</label>
                  <p>{alert.src_ip}</p>
                </div>
                <div className="detail-row">
                  <label>IP Destination</label>
                  <p>{alert.dst_ip}</p>
                </div>
                <div className="detail-row">
                  <label>Protocole / Port</label>
                  <p>{alert.protocol} / {alert.port}</p>
                </div>
                <div className="detail-row">
                  <label>Type d'attaque</label>
                  <p>{alert.attack_type}</p>
                </div>
                <div className="detail-row">
                  <label>Confiance</label>
                  <p>{(alert.confidence * 100).toFixed(0)}%</p>
                </div>
                <div className="detail-row">
                  <label>Explication</label>
                  <p>{alert.explanation}</p>
                </div>
                {alert.notes && (
                  <div className="detail-row">
                    <label>Note</label>
                    <p>{alert.notes}</p>
                  </div>
                )}
                <div className="alert-actions">
                  <button
                    className="btn btn-secondary"
                    onClick={() => handleAcknowledge(alert.id)}
                    disabled={alert.status !== 'new'}
                  >
                    Marquer comme reconnu
                  </button>
                  <button
                    className="btn btn-secondary"
                    onClick={() => handleAddNote(alert.id)}
                  >
                    Ajouter une note
                  </button>
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default AlertHistory;
